#!/usr/bin/env python3
"""Verify generated files carry an AUTO-GENERATED banner.

Two halves:

1. Committed generated files (only those whose generator needs a baserom,
   see generated/README.md) must self-mark in their first lines so nobody
   hand-edits them. The authoritative mark for diff-hiding is
   `.gitattributes` (linguist-generated); this check covers the
   human-facing half: the DO-NOT-EDIT banner.

2. The ROM-free generators (reloc stubs + reloc table) must still run and
   emit bannered output — they now write to <build>/generated via
   --out-dir, so this lint regenerates into a scratch dir and checks the
   banners there instead of assuming source-root outputs exist.

Formats that cannot carry a comment are exempt by design:
  - assets/game/**/manifests/*.json (pure JSON output;
    the content_hash inside is the integrity signal)
  - extraction YAMLs without the `reloc_` prefix are hand-authored ROM
    recipes — they are inputs, not generator output.
"""

import re
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]

COMMITTED_GLOBS = [
    "generated/src/*/ssb64_reloc_rebuild*.cpp",
    "assets/game/**/reloc_*.yml",
]

REGENERATED_GLOBS = [
    "include/*/reloc_data*.h",
    "src/*/RelocFileTable.??.*",
]

BANNER = re.compile(r"auto-?generated|generated by|do not edit", re.IGNORECASE)
SCAN_LINES = 15


def check_banners(base: Path, patterns, failures, label) -> int:
    checked = 0
    for pattern in patterns:
        for path in sorted(base.glob(pattern)):
            text = path.read_text(encoding="utf-8", errors="replace").splitlines()
            checked += 1
            if not any(BANNER.search(line) for line in text[:SCAN_LINES]):
                failures.append(f"{label}:{path.relative_to(base)}")
    return checked


def main() -> int:
    failures = []
    checked = check_banners(ROOT, COMMITTED_GLOBS, failures, "committed")

    with tempfile.TemporaryDirectory(prefix="ssb64-gen-lint-") as tmp:
        tools = ROOT / "tools" / "code-generation"
        for version in ("us", "jp"):
            for tool in ("generate_reloc_stubs.py", "generate_reloc_table.py"):
                subprocess.run(
                    [sys.executable, str(tools / tool),
                     "--version", version, "--out-dir", tmp],
                    cwd=ROOT, check=True, capture_output=True, text=True)
        checked += check_banners(Path(tmp), REGENERATED_GLOBS, failures, "regen")

    if failures:
        print("check_generated_headers: generated files missing an "
              "AUTO-GENERATED banner in the first "
              f"{SCAN_LINES} lines:")
        for f in failures:
            print(f"  {f}")
        print("Regenerate via the owning tool in tools/code-generation/ — "
              "do not hand-edit.")
        return 1
    print(f"check_generated_headers: clean ({checked} generated file(s))")
    return 0


if __name__ == "__main__":
    sys.exit(main())
